$ctrl.totalPages = Math.max(1, Math.ceil($ctrl.filteredPets.length / $ctrl.pageSize));
$ctrl.currentPage = Math.max(1, Math.min($ctrl.totalPages, Math.floor(Number($ctrl.currentPage) || 1)));
const offset = ($ctrl.currentPage - 1) * $ctrl.pageSize;
$ctrl.visiblePets = $ctrl.filteredPets.slice(offset, offset + $ctrl.pageSize);
$ctrl.rangeStart = $ctrl.filteredPets.length ? offset + 1 : 0;
$ctrl.rangeEnd = Math.min(offset + $ctrl.pageSize, $ctrl.filteredPets.length);

const query = String($ctrl.searchQuery || '').trim().toLocaleLowerCase();
const category = $ctrl.category;
const direction = $ctrl.sortOrder === 'desc' ? -1 : 1;
// Filtering creates a new array; never sort shared service data.
$ctrl.filteredPets = $ctrl.searchIndex.filter(entry => (!query || entry.text.includes(query)) && (category === '*' || 'category:' + entry.pet.category === category)).map(entry => entry.pet).sort((a, b) => direction * (a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }) || String(a.id).localeCompare(String(b.id))));
$ctrl.currentPage = 1;
$ctrl.slicePage();

const status = $ctrl.status;
const token = ++$ctrl.requestToken;
$ctrl.requestedStatus = status;
$ctrl.isLoading = true;
$ctrl.loadError = null;
$ctrl.updatedAt = null;
$ctrl.allPets = [];
$ctrl.searchIndex = [];
$ctrl.filteredPets = [];
$ctrl.categoryOptions = [{ label: 'All categories', value: '*' }];
$ctrl.currentPage = 1;
$ctrl.slicePage();
// $q handles synchronous service failures as well as rejected service promises.
return $ctrl.$q.when().then(() => $ctrl.petData.loadPets(status, !!force)).then(list => {
  if (token !== $ctrl.requestToken || status !== $ctrl.status) { return; }
  if (!Array.isArray(list)) { throw new Error('The pet service returned an invalid list. Please retry.'); }
  $ctrl.allPets = list.slice();
  $ctrl.searchIndex = $ctrl.allPets.map(pet => ({ pet: pet, text: [pet.name, pet.category, String(pet.id)].concat(pet.tags).join(' ').toLocaleLowerCase() }));
  const categories = Array.from(new Set($ctrl.allPets.map(pet => pet.category))).sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
  $ctrl.categoryOptions = [{ label: 'All categories', value: '*' }].concat(categories.map(name => ({ label: name, value: 'category:' + name })));
  if (!$ctrl.categoryOptions.some(option => option.value === $ctrl.category)) { $ctrl.category = '*'; }
  // Only use a timestamp proven to describe this exact public service list.
  if ($ctrl.petData.currentStatus === status && $ctrl.petData.pets === list) {
    $ctrl.updatedAt = $ctrl.petData.lastUpdated;
  }
  $ctrl.applyFilters();
}).catch(err => {
  if (token !== $ctrl.requestToken || status !== $ctrl.status) { return; }
  $ctrl.loadError = (err && err.message) || 'Unable to load pets. Please try again.';
  $ctrl.allPets = [];
  $ctrl.searchIndex = [];
  $ctrl.applyFilters();
}).finally(() => {
  if (token === $ctrl.requestToken && status === $ctrl.status) { $ctrl.isLoading = false; }
});
